  "codebook": {
    "definition": "Credit-claiming refers to statements in which a legislator asserts personal or collective responsibility for a desirable policy outcome, legislative action, or the allocation of federal resources (such as grants, projects, or infrastructure) that benefit their constituents or align with their policy goals.",
    "clarification": "A text should be classified as 'credit-claiming' if the senator highlights their active role in introducing, sponsoring, or passing legislation, securing funding, negotiating a compromise, or directly influencing an agency's decision. Words indicating action and ownership like 'secured', 'authored', 'introduced', 'fought for', 'helped pass', or 'my amendment' signify credit-claiming. Furthermore, the standard practice of a senator announcing a local grant award generally counts as credit-claiming, as it is designed to associate the member of Congress with the delivery of federal funds to their district.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'delivered on their promise to secure federal funding' and 'went to bat for these dollars,' directly asserting responsibility for bringing money to their state."
      },
      {
        "document_id": "2697",
        "explanation": "The senator clearly takes credit for securing resources by stating that when one agency denied funding, 'I then went looking and found another federal funding source' to solve the problem."
      },
      {
        "document_id": "4585",
        "explanation": "The senator announces local fire department grants and explicitly ties the money to his own legislative efforts by stating he 'pushed for Additional Funding' and was 'among the first senators who recognized the need' for the program."
      }
    ],
    "negative_clarification": "A text is NOT credit-claiming if the senator merely expresses an opinion on a policy, criticizes opponents, comments on a current event, pays tribute to an individual, or makes a statement without asserting any personal responsibility for a tangible outcome or specific legislative action. Mentioning that they cosponsored a bill that failed, or welcoming an agency's decision without claiming to have influenced it, is considered position-taking rather than credit-claiming.",
    "negative_examples": [
      {
        "document_id": "453",
        "explanation": "The senator releases a statement explaining his position on setting measurable goals in Iraq. He is expressing a policy preference rather than claiming credit for a specific legislative achievement or federal grant."
      },
      {
        "document_id": "656",
        "explanation": "The senator criticizes the administration's handling of a ports deal. This is partisan position-taking and criticism, not an assertion of credit for a policy outcome."
      },
      {
        "document_id": "2143",
        "explanation": "The senator issues a statement mourning the passing of a state political leader. This is a ceremonial tribute and does not contain any legislative or policy credit-claiming."
      }
    ]
  }
}
